(()=>{let arrival=false;try{arrival=sessionStorage.getItem('starwish.arrival')==='yes';sessionStorage.removeItem('starwish.arrival')}catch{}if(arrival&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const scene=document.querySelector('.lobby');scene.classList.add('arriving');window.setTimeout(()=>scene.classList.remove('arriving'),700)}window.addEventListener('pageshow',e=>{if(e.persisted)document.querySelector('.lobby').classList.remove('arriving')})})();

(()=>{const dialog=document.querySelector('#panel'),body=document.querySelector('#panel-body');
const heroes=HeroData.heroes;
function motion(){let enabled=!matchMedia('(prefers-reduced-motion: reduce)').matches;try{const saved=localStorage.getItem('starwish.homeMotion');if(saved!==null)enabled=saved==='on'}catch{}document.querySelector('.lobby').classList.toggle('still',!enabled);return enabled}motion();const messages={'旅人':'歡迎來到星界。集結夥伴，從森林試煉開始你的遠征。','資源':'金幣與星晶將在養成及召喚系統完成後啟用，目前尚未設定初始資源。','任務':'任務系統準備中。先前往森林試煉，體驗五人編隊與必殺技。','信箱':'目前沒有信件。','召喚':'星辰召喚準備中，之後將開放單次召喚與十連召喚。','背包':'背包準備中，目前尚無可管理的道具。','放置收益':'放置收益將在關卡獎勵與資源規則確認後開放，目前尚未累積收益。'};document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>{const name=b.dataset.panel;if(name==='大廳')return;if(name==='角色'){location.href='characters.html';return;}if(name==='召喚'){location.href='summon.html';return;}document.querySelector('#panel-title').textContent=name;if(name==='角色'){body.innerHTML='<p>目前戰鬥測試角色，可在戰前編隊中選擇最多五人。</p><div class="hero-grid">'+heroes.map(hero=>`<figure><img src="${hero.portrait}" alt="${hero.name}"><figcaption>${hero.name}<small>${hero.role}</small>${hero.id==='garnet'?'<a href="starboard.html">星盤培養</a>':''}</figcaption></figure>`).join('')+'</div><a class="primary" href="chapter.html">前往戰前編隊</a>'}else if(name==='放置收益'){IdleRewards.show(body)}else if(name==='設定'){body.innerHTML='<label class="setting-row">大廳星光動畫<input id="lobby-motion" type="checkbox" role="switch"></label><a class="secondary" href="./">返回標題畫面</a>';const toggle=body.querySelector('input');toggle.checked=motion();toggle.onchange=()=>{document.querySelector('.lobby').classList.toggle('still',!toggle.checked);try{localStorage.setItem('starwish.homeMotion',toggle.checked?'on':'off')}catch{}}}else{body.innerHTML='<p>'+messages[name]+'</p>'+(['旅人','任務'].includes(name)?'<a class="primary" href="chapter.html">前往森林試煉</a>':'')}dialog.showModal()});document.querySelector('#panel-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}})})();
